mapper.select:
SELECT
    (SUM(IFNULL(mpw.total_net_weight, 0)) / 1000) AS total_inbound_quantity,
    SUM(IFNULL(mpw.total_wage, 0)) AS total_salary
FROM mes_production_wage mpw
WHERE mpw.bool_delete_enum = FALSE
  AND mpw.bool_confirm = TRUE
  AND DATE_FORMAT(mpw.inbound_time, '%Y-%m-%d') BETWEEN #{startDate} AND #{endDate}

    and mpw.workshop_id = #{workshopId}


    and mpw.project_id = #{projectId}

SELECT this_month.*, IFNULL(lastMonth.yield, 0) AS last_month_yield, IFNULL(lastMonth.money, 0) AS last_month_money, mbw.name AS workshop_name, mbp.name as process_name FROM ( SELECT mpw.workshop_id, mpw.process_id, mpw.team_leader_name, mbt.organization_type as team_organization_type, (SUM(IFNULL(mpw.yield, 0)) / 1000) AS yield, SUM(IFNULL(mpw.total_wage, 0)) AS money FROM mes_production_wage mpw left join mes_building_team mbt on mbt.bool_delete_enum = FALSE and mbt.id = mpw.team_id WHERE mpw.bool_delete_enum = FALSE AND mpw.bool_confirm = TRUE AND DATE_FORMAT(mpw.inbound_time, '%Y-%m-%d') BETWEEN #{startDate} AND #{endDate}
and mpw.workshop_id = #{workshopId}
and mpw.project_id = #{projectId}
GROUP BY mpw.workshop_id, mpw.process_id, mpw.team_leader_name, mbt.organization_type ) this_month LEFT JOIN ( SELECT mpw.workshop_id, mpw.process_id, mpw.team_leader_name, mbt.organization_type as team_organization_type, (SUM(IFNULL(mpw.yield, 0)) / 1000) AS yield, SUM(IFNULL(mpw.total_wage, 0)) AS money FROM mes_production_wage mpw left join mes_building_team mbt on mbt.bool_delete_enum = FALSE and mbt.id = mpw.team_id WHERE mpw.bool_delete_enum = FALSE AND mpw.bool_confirm = TRUE AND DATE_FORMAT(mpw.inbound_time, '%Y-%m-%d') BETWEEN #{lastMonthStartDate} AND #{lastMonthEndDate}
and mpw.workshop_id = #{workshopId}
GROUP BY mpw.workshop_id, mpw.process_id, mpw.team_leader_name, mbt.organization_type ) lastMonth ON lastMonth.workshop_id = this_month.workshop_id AND lastMonth.process_id = this_month.process_id AND lastMonth.team_leader_name = this_month.team_leader_name LEFT JOIN mes_building_workshop mbw ON mbw.bool_delete_enum = FALSE AND mbw.id = this_month.workshop_id LEFT JOIN mes_building_process mbp on mbp.bool_delete_enum = FALSE and mbp.id = this_month.process_id
